package com.dramastudio.service;
import com.dramastudio.config.JwtService; import com.dramastudio.entity.User; import com.dramastudio.repository.UserRepository; import java.time.Instant; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.util.LinkedMultiValueMap; import org.springframework.web.client.RestClient;
@Service public class AuthService {
 private final UserRepository users; private final JwtService jwt; private final RestClient http=RestClient.create();
 @Value("${app.oauth.client-id}") String clientId; @Value("${app.oauth.client-secret}") String secret; @Value("${app.oauth.redirect-uri}") String redirect; @Value("${app.oauth.token-url}") String tokenUrl; @Value("${app.oauth.userinfo-url}") String userInfoUrl;
 public AuthService(UserRepository u,JwtService j){users=u;jwt=j;}
 @SuppressWarnings("unchecked") public String exchange(String code){var form=new LinkedMultiValueMap<String,String>();form.add("client_id",clientId);form.add("client_secret",secret);form.add("code",code);form.add("grant_type","authorization_code");form.add("redirect_uri",redirect);Map<String,Object> token=http.post().uri(tokenUrl).contentType(MediaType.APPLICATION_FORM_URLENCODED).body(form).retrieve().body(Map.class);String access=Objects.toString(token.get("access_token"));Map<String,Object> info=http.get().uri(userInfoUrl).header("Authorization","Bearer "+access).retrieve().body(Map.class);String username=Objects.toString(info.get("username"));User u=users.findByAiConnectUsername(username).orElseGet(()->{User x=new User();x.aiConnectUsername=username;x.username=username;x.email=(String)info.get("email");return x;});u.lastLoginAt=Instant.now().toString();users.save(u);return jwt.issue(u.id,u.username,u.role);}
}
